curl -s http://127.0.0.1:4000/api/events/status    # state, cursor, checkpoint (last stream seq), pending, history_gap
curl -s 'http://127.0.0.1:4000/api/events?subject=bloodbank.evt.conversation.turn.started&after=<cursor>&limit=500'   # items[] {cursor,stream,sequence,subject,collected_at,envelope}
curl -N http://127.0.0.1:4000/api/events/stream?after=<cursor>   # SSE live tail, Last-Event-ID resume
